                found=True
        if not found: break
    return res

def solve(g):
    # build tree: children = comps strictly inside another comp
    H,W=len(g),len(g[0])
    cs=comps(g)
    bboxes={}
    for v,c in cs: ys=[r for r,_ in c]; xs=[cc for _,cc in c]
    bboxes[v]=(min(ys),max(ys),min(xs),max(xs),c)
    # depth: root comps (no comp strictly contains them except bg) ordered
    def depth(v,bbox):
        d=1
        while True:
            contained=False
            for vv,(ry_,ry__,cx_,cx__) in [(v,bboxes[v])] or [(None,None)]:
                pass
            enc=[vv for vv,(rr,rrr,cc,ccc,_) in bboxes.items()
                 if vv!=v and rr<=bbox[0] and rrr>=bbox[1] and cc<=bbox[2] and ccc>=bbox[3]]
            if not enc: break
            d+=1
        return d
    roots=[]
    for v,(r0,r1,c0,c1,c) in bboxes.items():
        if all(False for vv,(rr,rrr,cc,ccc,_) in bboxes.items() if vv!=v and rr<=r0 and rrr>=r1 and cc<=c0 and ccc>=c1):
            roots.append(v)
    # rank roots by bbox size descending
    roots.sort(key=lambda v:(bboxes[v][1]-bboxes[v][0])*bboxes[v][3]-bboxes[v][2], reverse=True)
    ranks={r:i+1 for i,r in enumerate(roots)}
    # for non-root comps, parent = smallest comp containing bbox
    for v,(r0,r1,c0,c1,c) in bboxes.items():
        if ranks.get(v) is None:
            parents=[(vv,bboxes[vv][0]) for vv in bboxes if v not in (vv,) ]
            best=min([bboxes[vv] for vv in bboxes if vv!=v and bboxes[vv][0]<=r0 and bboxes[vv][1]>=r1 and bboxes[vv][2]<=c0 and bboxes[vv][3]>=c1], key=lambda b:b[1]-b[0])
            if parents: ranks[v]=ranks[best]+1
    return ranks,cs,bboxes

