def build_tree(cs):
    n=len(cs)
    ranks={}
    for idx,(v,c) in enumerate(cs):
        ys=[r for r,_ in c]; xs=[cc for _,cc in c]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        enc=[jj for jj,(vv,cc2) in enumerate(cs) if vv!=0 and (min([r for r,_ in cc2])<=r0 and max([r for r,_ in cc2])>=r1 and min([c for _,c in cc2])<=c0 and max([c for _,c in cc2])>=c1) and len(set(c)&set(cc2))>0 and (min([r for r,_ in cc2]),max([r for r,_ in cc2]))!=(r0,r1) or False]
        # strict enclosure by bbox corners with different content inside
        best=None
        for jj,(vv,cc2) in enumerate(cs):
            if vv==0: continue
            ys2=[r for r,_ in cc2]; xs2=[cc for _,cc in cc2]
            a,b,aa,bb=min(ys2),max(ys2),min(xs2),max(xs2)
            if a<r0 and b>r1 and aa<c0 and bb>c1:
                # does it actually contain? check any cell of cc2 outside ours
                outside=sum(1 for p in cc2 if not (r0<=p[0]<=r1 and c0<=p[1]<=c1))
                if outside>0:
                    if best is None or (b-a)*(bb-aa)<(r1-r0)*(c1-c0):
                        best=jj
        ranks[idx]=best
    return ranks
