def solve(g):
    cs=comps(g)
    nz=[(v,c) for v,c in cs if v!=0]
    bb=[bbox(c) for v,c in nz]
    n=len(nz)
    # parent: smallest comp whose bbox strictly contains ours
    P=[None]*n
    for i in range(n):
        b=bb[i]
        cand=[j for j in range(n) if j!=i and b[0]>bb[j][0] and b[1]<bb[j][1] and b[2]>bb[j][2] and b[3]<bb[j][3]]
        if cand:
            P[i]=min(cand,key=lambda j:(bb[j][1]-bb[j][0])*(bb[j][3]-bb[j][2]))
        else:
            P[i]=-1   # root of its cluster
    # find cluster roots: nodes reachable with path of parents ending at -1
    clusters=[]; seen=set()
    for s in range(n):
        if s in seen: continue
        st=[s]; fam=set()
