            idx=st.pop()
            if idx in fam: continue
            fam.add(idx); seen.add(idx)
            p=P[idx]
            if p!=-1 and p not in fam: st.append(p)
        clusters.append(fam)
    res=[row[:] for row in g]
    for fam in clusters:
        children={}
        for i in fam: children.setdefault(P[i],[]).append(i)
        roots=[i for i in fam if P[i]==-1]
        df={i:0 for i in roots}
        q=deque(roots)
        while q:
            u=q.popleft()
            for v in children[u]:
